#include "settings.h"
#include <Preferences.h>
static Preferences prefs;
void SettingsStore::begin(){prefs.begin("rf430",false);}
void SettingsStore::load(MeasurementConfig&c){uint8_t v;AdcConfig a;if(decodeAdcConfig(prefs.getUChar("adc1",0x18),a))c.adc1=a;if(decodeAdcConfig(prefs.getUChar("adc2",0x18),a))c.adc2=a;if(decodeAdcConfig(prefs.getUChar("adc0",0x18),a))c.adc0=a;c.adc1Enabled=prefs.getBool("e1",true);c.adc2Enabled=prefs.getBool("e2",true);c.adc0Enabled=prefs.getBool("e0",false);c.adc1Role=RF430::ChannelRole(prefs.getUChar("r1",1));c.adc2Role=RF430::ChannelRole(prefs.getUChar("r2",2));c.referenceOhm=prefs.getDouble("rref",200000);c.r0Ohm=prefs.getDouble("r0",0);c.gaugeFactor=prefs.getDouble("gf",2);c.frequency=prefs.getUChar("freq",3);c.passes=prefs.getUShort("pass",1);c.averaging=prefs.getUChar("avg",1);c.infinite=prefs.getBool("inf",false);c.resistiveBias=prefs.getBool("bias",true);}
void SettingsStore::save(const MeasurementConfig&c){uint8_t v;encodeAdcConfig(c.adc1,v);prefs.putUChar("adc1",v);encodeAdcConfig(c.adc2,v);prefs.putUChar("adc2",v);encodeAdcConfig(c.adc0,v);prefs.putUChar("adc0",v);prefs.putBool("e1",c.adc1Enabled);prefs.putBool("e2",c.adc2Enabled);prefs.putBool("e0",c.adc0Enabled);prefs.putUChar("r1",uint8_t(c.adc1Role));prefs.putUChar("r2",uint8_t(c.adc2Role));prefs.putDouble("rref",c.referenceOhm);prefs.putDouble("r0",c.r0Ohm);prefs.putDouble("gf",c.gaugeFactor);prefs.putUChar("freq",c.frequency);prefs.putUShort("pass",c.passes);prefs.putUChar("avg",c.averaging);prefs.putBool("inf",c.infinite);prefs.putBool("bias",c.resistiveBias);}
